//! End-to-end tests for passive `ComponentSpec` registration, lazy on-demand
//! activation, dual-key CBOR / JSON translation, `TaggedRecord` sessions, and
//! `quic-mux` `FramedStream` dispatch using code generated by `mesh-api-gen --out-component`.

use std::sync::Arc;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::time::Duration;

use mesh_api::cbor::Encoder;
use mesh::quic_mux::{TokioMux, TokioMuxConfig};
use mesh::registry::ServiceRegistry;
use mesh::tagged::{NameOrTag, TaggedRecord};
use mesh::wire::{read_cbor_record, serve_cbor_session, write_cbor_record};
use mesh::{
    ComponentDirectory, FramedStream, MeshStream, OwnedEnvelope, StaticComponent,
    read_envelope_prefix,
};
use mesh_api::envelope::{Name, PrefixDecode, decode_envelope_prefix};
use serde_json::json;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

#[allow(dead_code)]
mod generated {
    include!("fixtures/demo_component.rs");
}

use generated::*;

static DEMO_INITS: AtomicUsize = AtomicUsize::new(0);
static HOST_INFO_INITS: AtomicUsize = AtomicUsize::new(0);

struct DemoService;

impl Default for DemoService {
    fn default() -> Self {
        DEMO_INITS.fetch_add(1, Ordering::SeqCst);
        Self
    }
}

#[async_trait::async_trait]
impl DemoComponent for DemoService {
    async fn greet(&self, request: DemoGreetRequest) -> anyhow::Result<DemoGreetResponse> {
        let count = usize::from(request.repeat.unwrap_or(1).max(1));
        let unit = format!("hello {}", request.name);
        let message = vec![unit; count].join(", ");
        Ok(DemoGreetResponse { message })
    }

    async fn upper_stream(
        &self,
        request: DemoUpperStreamRequest,
        envelope: OwnedEnvelope,
        mut stream: FramedStream<Box<dyn MeshStream>>,
    ) -> anyhow::Result<()> {
        let mut body = Vec::new();
        stream.read_to_end(&mut body).await?;
        let mut out_body = Vec::new();
        if let Some(prefix) = request.prefix {
            out_body.extend_from_slice(prefix.as_bytes());
        }
        for byte in body {
            out_body.push(byte.to_ascii_uppercase());
        }

        // Write correlated response envelope `{1: 15, 2: 2, 3: id, 6: {}}` followed by raw body.
        let mut resp_hdr = [0u8; 64];
        let hdr_len = mesh_api::envelope::encode_numeric_response(
            15,
            2,
            envelope.id.unwrap_or(0),
            &[0xa0],
            &mut resp_hdr,
        )
        .expect("encode response header");
        stream.write_all(&resp_hdr[..hdr_len]).await?;
        stream.write_all(&out_body).await?;
        stream.shutdown().await?;
        Ok(())
    }
}

struct HostInfoService {
    calls: AtomicU64,
}

impl Default for HostInfoService {
    fn default() -> Self {
        HOST_INFO_INITS.fetch_add(1, Ordering::SeqCst);
        Self {
            calls: AtomicU64::new(0),
        }
    }
}

#[async_trait::async_trait]
impl HostInfoComponent for HostInfoService {
    async fn status(&self, _request: HostInfoStatusRequest) -> anyhow::Result<HostInfoStatusResponse> {
        let calls = self.calls.fetch_add(1, Ordering::SeqCst) + 1;
        Ok(HostInfoStatusResponse {
            healthy: true,
            calls,
        })
    }
}

/// Passive compile-time table in `.rodata`: zero code runs before a request arrives!
const BUILTINS: &[StaticComponent] = &[
    demo_static_default::<DemoService, ()>(),
    host_info_static_default::<HostInfoService, ()>(),
];

#[tokio::test]
async fn generated_components_activate_on_demand_and_support_json_dual_cbor_and_mux_streams() {
    DEMO_INITS.store(0, Ordering::SeqCst);
    HOST_INFO_INITS.store(0, Ordering::SeqCst);

    let dir = Arc::new(
        ComponentDirectory::from_static(BUILTINS, ())
            .with_service_registry(ServiceRegistry::new("test-host")),
    );

    // 1. Neither component was instantiated during `from_static`.
    assert_eq!(dir.component_names(), vec!["demo", "host.info"]);
    assert_eq!(DEMO_INITS.load(Ordering::SeqCst), 0);
    assert_eq!(HOST_INFO_INITS.load(Ordering::SeqCst), 0);

    // 2. Calling string-only `host.info.status` activates ONLY `host.info`, leaving `demo` idle!
    let status_json = dir
        .call_json("host.info", "status", json!({}))
        .await
        .unwrap();
    assert_eq!(status_json, json!({ "healthy": true, "calls": 1 }));
    assert_eq!(HOST_INFO_INITS.load(Ordering::SeqCst), 1);
    assert_eq!(DEMO_INITS.load(Ordering::SeqCst), 0);

    // 3. Dual-key CBOR: calling `demo.greet` with UTF-8 string map keys `{"name": "Ada", "repeat": 2}`
    //    AND with numeric field tags `{1: "Bob"}` both work directly without JSON conversion!
    let mut string_key_cbor = [0u8; 64];
    let sk_len = {
        let mut e = Encoder::new(&mut string_key_cbor);
        e.map(2).unwrap();
        e.str(b"name").unwrap();
        e.str(b"Ada").unwrap();
        e.str(b"repeat").unwrap();
        e.uint(2).unwrap();
        e.len()
    };
    let resp_cbor = dir
        .call_cbor(
            Name::Text(b"demo"),
            Name::Text(b"greet"),
            &string_key_cbor[..sk_len],
        )
        .await
        .unwrap();
    let decoded = DemoGreetResponse::decode_cbor(&resp_cbor).unwrap();
    assert_eq!(decoded.message, "hello Ada, hello Ada");
    assert_eq!(DEMO_INITS.load(Ordering::SeqCst), 1);

    let tag_key_cbor = (DemoGreetRequest {
        name: "Bob".to_owned(),
        repeat: None,
    })
    .encode_cbor();
    let resp_cbor_2 = dir
        .call_cbor(Name::Tag(15), Name::Tag(1), &tag_key_cbor)
        .await
        .unwrap();
    let decoded_2 = DemoGreetResponse::decode_cbor(&resp_cbor_2).unwrap();
    assert_eq!(decoded_2.message, "hello Bob");
    assert_eq!(DEMO_INITS.load(Ordering::SeqCst), 1);

    // 4. TaggedRecord session (`serve_cbor_session`): supports both common `mesh.initialize`
    //    and component calls with named or numeric tags!
    let (mut cbor_client, mut cbor_server) = tokio::io::duplex(4096);
    let session_dir = Arc::clone(&dir);
    let session_task =
        tokio::spawn(async move { serve_cbor_session(&mut cbor_server, session_dir.as_ref()).await });

    write_cbor_record(
        &mut cbor_client,
        &TaggedRecord {
            component: NameOrTag::Name("mesh".into()),
            method: NameOrTag::Name("initialize".into()),
            id: Some(json!(1)),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let init_reply = read_cbor_record(&mut cbor_client).await.unwrap().unwrap();
    assert_eq!(init_reply.result.unwrap()["1"], "test-host");

    let mut env = std::collections::BTreeMap::new();
    env.insert(NameOrTag::Name("name".into()), json!("Mesh"));
    write_cbor_record(
        &mut cbor_client,
        &TaggedRecord {
            component: NameOrTag::Name("demo".into()),
            method: NameOrTag::Name("greet".into()),
            id: Some(json!(2)),
            env,
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let greet_reply = read_cbor_record(&mut cbor_client).await.unwrap().unwrap();
    assert_eq!(greet_reply.result.unwrap()["1"], "hello Mesh");
    cbor_client.shutdown().await.unwrap();
    session_task.await.unwrap().unwrap();

    // 5. Real `quic-mux` (`TokioMux`) multiplexed stream session:
    //    Open two concurrent streams over one `TokioMux` link—one bidirectional `demo.upper_stream`
    //    and one unary `demo.greet`—and serve both through `ComponentDirectory::serve_stream`!
    let (mux_client_io, mux_server_io) = tokio::io::duplex(16 * 1024);
    let (client_mux, _client_acceptor) = TokioMux::client(mux_client_io, TokioMuxConfig::default());
    let (_server_mux, mut server_acceptor) =
        TokioMux::server(mux_server_io, TokioMuxConfig::default());

    let accept_dir = Arc::clone(&dir);
    let accept_task = tokio::spawn(async move {
        for _ in 0..2 {
            let incoming = server_acceptor.accept().await.expect("accept mux stream");
            let d = Arc::clone(&accept_dir);
            tokio::spawn(async move {
                d.serve_stream(incoming).await.unwrap();
            });
        }
    });

    // Stream A: `demo.upper_stream` (component 15, method 2) with prefix `">> "` + body `"quic-mux!"`
    let mut stream_a = client_mux.open_bidi().await.unwrap();
    let stream_req_fields = (DemoUpperStreamRequest {
        prefix: Some(">> ".to_owned()),
    })
    .encode_cbor();
    let mut stream_hdr = [0u8; 96];
    let sh_len = {
        let mut e = Encoder::new(&mut stream_hdr);
        e.map(4).unwrap();
        e.uint(1).unwrap();
        e.uint(15).unwrap();
        e.uint(2).unwrap();
        e.uint(2).unwrap();
        e.uint(3).unwrap();
        e.uint(101).unwrap();
        e.uint(5).unwrap();
        e.encoded_value(&stream_req_fields).unwrap();
        e.len()
    };
    stream_a.write_all(&stream_hdr[..sh_len]).await.unwrap();
    stream_a.write_all(b"quic-mux!").await.unwrap();
    stream_a.shutdown().await.unwrap();

    let (resp_env_a, mut framed_a) = read_envelope_prefix(&mut stream_a).await.unwrap();
    assert_eq!(resp_env_a.id, Some(101));
    let mut out_body = Vec::new();
    framed_a.read_to_end(&mut out_body).await.unwrap();
    assert_eq!(out_body, b">> QUIC-MUX!");

    // Stream B: unary `demo.greet` over a `TokioMux` stream using string identifiers!
    let mut stream_b = client_mux.open_bidi().await.unwrap();
    let unary_fields = (DemoGreetRequest {
        name: "Mux".to_owned(),
        repeat: None,
    })
    .encode_cbor();
    let mut unary_hdr = [0u8; 96];
    let uh_len = {
        let mut e = Encoder::new(&mut unary_hdr);
        e.map(4).unwrap();
        e.uint(1).unwrap();
        e.str(b"demo").unwrap();
        e.uint(2).unwrap();
        e.str(b"greet").unwrap();
        e.uint(3).unwrap();
        e.uint(102).unwrap();
        e.uint(5).unwrap();
        e.encoded_value(&unary_fields).unwrap();
        e.len()
    };
    stream_b.write_all(&unary_hdr[..uh_len]).await.unwrap();
    stream_b.shutdown().await.unwrap();

    let mut raw_reply = Vec::new();
    stream_b.read_to_end(&mut raw_reply).await.unwrap();
    let PrefixDecode::Complete { record, .. } = decode_envelope_prefix(&raw_reply) else {
        panic!("expected complete unary response envelope");
    };
    assert_eq!(record.id, Some(102));
    let mux_greet = DemoGreetResponse::decode_cbor(record.result.unwrap()).unwrap();
    assert_eq!(mux_greet.message, "hello Mux");

    accept_task.await.unwrap();

    // 6. Idle eviction reclaims both components once streams complete.
    tokio::time::sleep(Duration::from_millis(5)).await;
    assert_eq!(dir.evict_idle(Duration::ZERO), 2);
    assert!(!dir.is_active("demo"));
    assert!(!dir.is_active("host.info"));
}
